head.script:
scwin.screenId = "jldbnf60100";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurNm")))); } },
        { childId: "__rb1", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_showSriBndRegListReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":8
        ,"mmenu":0
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf60100' }); }

scwin.initSriBndAppl = initSriBndAppl;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf60100.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.table_101_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.table_101_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'file_cnt') { var __d = $c.util.getComponent('dlt_sriappl'); if (!__d) { return; } if (Number(__d.getCellData(rowIndex, "file_cnt")) > 0) { if (typeof scwin.showEtcFileList === 'function') { await scwin.showEtcFileList(String(__d.getCellData(rowIndex, "std_cd")), String(__d.getCellData(rowIndex, "appl_isu_seq"))); } else { console.error('[sdd] 행 동작 미정의: scwin.showEtcFileList (열 file_cnt)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.showEtcFileList'); } } return; } if (columnId === 'stat') { var __d = $c.util.getComponent('dlt_sriappl'); if (!__d) { return; } if (String(__d.getCellData(rowIndex, "stat")) === "반송") { if (typeof scwin.OpenRetViewSri === 'function') { await scwin.OpenRetViewSri(String(__d.getCellData(rowIndex, "std_cd")), String(__d.getCellData(rowIndex, "appl_isu_seq"))); } else { console.error('[sdd] 행 동작 미정의: scwin.OpenRetViewSri (열 stat)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.OpenRetViewSri'); } } return; } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60100.table_101_oncellclick' }); }
};

