        /* sdd-asis-lifecycle:begin ipt_searchWord_onkeypress — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        replacePercent(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60100.ipt_searchWord_onkeypress' }); }
};

