/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: focus_tr (인자 미해석) · fn_initSriBndAppl(${status.count-1}, ${fn:length(result)}); (EL 미해석) */
        if (columnId === "radioCheck") { console.error('[sdd] 미실현 행 동작: fn_initSriBndAppl (as-is 인자를 못 옮겼습니다)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — fn_initSriBndAppl'); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_showSriBndRegList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_showSriBndRegList = async function () {
    const sbmOptions = {
        id: "tx_fn_showSriBndRegList",
        method: "post",
        action: "/sri/sribnd.do",
        ref: "dma_showSriBndRegListReq",
        target: "dlt_sriappl=sriappl",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf60100.tx_fn_showSriBndRegList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

