///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.table_101_fmt_appl_dd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData rowIndex columnIndex
 * @returns
 * @hidden N
*/
scwin.table_101_fmt_appl_dd = function (data, formattedData, rowIndex, columnIndex) { const d = $c.util.getComponent('dlt_sriappl'); const b = d ? d.getCellData(rowIndex, "appl_tm") : ''; return ((data === undefined || data === null) ? '' : String(data)) + '<br>' + ((b === undefined || b === null) ? '' : String(b)); };

/**
 * @method
 * @name scwin.table_101_fmt_file_cnt
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData rowIndex columnIndex
 * @returns
 * @hidden N
*/
scwin.table_101_fmt_file_cnt = function (data, formattedData, rowIndex, columnIndex) { if (Number(data) > 0) { return "<a href=\"javascript:void(0)\">열기</a>"; } return (data === undefined || data === null) ? '' : String(data); };

/**
 * @method
 * @name scwin.table_101_fmt_stat
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData rowIndex columnIndex
 * @returns
 * @hidden N
*/
scwin.table_101_fmt_stat = function (data, formattedData, rowIndex, columnIndex) { if (String(data) === "반송") { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; } return (data === undefined || data === null) ? '' : String(data); };

/**
 * @event
 * @name scwin.__on_enter_1_ipt_searchWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_1_ipt_searchWord = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_1_ipt_searchWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.showSriBndRegList() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60100.__on_enter_1_ipt_searchWord' }); }
};

/**
 * @method
 * @name scwin.showSriBndRegList
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.showSriBndRegList = async function (div) {
    /* sdd-asis-lifecycle:begin fn_showSriBndRegList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SearchForm || { elements: [] });
    if (div === 'button') {
        $c.util.getComponent('dma_showSriBndRegListReq').set('pageIndex', "1");
    }
    $c.util.getComponent("dma_showSriBndRegListReq").set("method", "showSriBndRegList");
    fm.action = '/sri/sribnd.do';
    fm.target = "_self";
    await scwin.tx_fn_showSriBndRegList();
    /* sdd-asis-lifecycle:end */
};


async function initSriBndAppl(rowIdx, rownum) {
    /* sdd-asis-lifecycle:begin fn_initSriBndAppl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SearchForm || { elements: [] });
    if (rownum == 1) {
        $c.util.getComponent("dma_showSriBndRegListReq").set("sndStdCd", $c.util.getComponent("dma_showSriBndRegListReq").get("stdCd"));
    } else {
        if (rownum > 1) {
            $c.util.getComponent("dma_showSriBndRegListReq").set("sndStdCd", $c.util.getComponent('dlt_result').getCellData(rowIdx, 'isuCd'));
        }
    }
    $.ajax({ type: "POST", async: false, url: "../ajax/sri_data.jsp", data: $("#SearchForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const rowPlus = $c.util.getComponent("tbl_appl");
                let tr;
                let th;
                let td;
                let $tblAppl;
                let $tr;
                let $td1, $td2, $td3, $td4, $td5, $td6, $td7, $td8, $td9, $td10;
                /* 표 비움 → setJSON 전체 교체가 대신(표 앵커) */
                $c.util.getComponent('dlt_sriappl').setJSON(scwin.result.sriappl); /* as-is 조립 루프 → 그리드 공급으로 대체(표 앵커 #tbl_appl): 행은 dlt_sriappl 가 싣고 열 동작은 그리드가 낸다 · 빈 갈래까지 함께(그리드 빈 표시가 「데이터가 없습니다」를 대신한다) */
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 서버에서 ESG채권 신청현황을 가져올 수 없습니다. 관리자에게 문의하세요.");
                return;
            }, complete: function() {

            } });
    await scwin.tx_fn_initSriBndAppl();

    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.showSriBndRegView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.showSriBndRegView = async function () {
    /* sdd-asis-lifecycle:begin fn_showSriBndRegView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.check_procs_yn();
    const fm = (document.SearchForm || { elements: [] });
    if ($c.util.getComponent("dma_showSriBndRegListReq").get("sndStdCd") === '') {
        await $c.win.alert('종목을 선택하세요.');
        return;
    } else {
        if ($c.util.getComponent("dma_showSriBndRegListReq").get("checkProcsCnt") > 0) {
            await $c.win.alert('이미 신청되었습니다.');
            return;
        } else {
            $c.util.getComponent("dma_showSriBndRegListReq").set("method", 'showSriBndRegView');
            fm.action = '/sri/sribnd.do?std_cd=' + $c.util.getComponent("dma_showSriBndRegListReq").get("sndStdCd");
            fm.target = "_self";
            await scwin.tx_fn_showSriBndRegView();
        }
    }
    /* sdd-asis-lifecycle:end */
};


