/**
 * @method
 * @name scwin.focus_tr
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.focus_tr = async function (obj) {
    /* sdd-asis-lifecycle:begin focus_tr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const radio = document.getElementsByName("radio_check");
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
        radio[i].checked = false;
    }
    obj.className = 'on';
    radio[obj.rowIndex -1].checked = true;
    await initSriBndAppl(obj.rowIndex - 1, obj.parentNode.children.length);
    /* sdd-asis-lifecycle:end */
};


